html = open("/tmp/yt_page.html", encoding="utf-8", errors="ignore").read()

# Find ytInitialPlayerResponse start
idx = html.find("ytInitialPlayerResponse")
print("idx:", idx)
if idx > -1:
    # Find the opening brace after =
    start = html.find("{", idx)
    # Find matching closing brace (balanced)
    depth = 0
    end = start
    in_str = False
    esc = False
    for i in range(start, len(html)):
        c = html[i]
        if in_str:
            if esc:
                esc = False
            elif c == "\\":
                esc = True
            elif c == '"':
                in_str = False
        else:
            if c == '"':
                in_str = True
            elif c == "{":
                depth += 1
            elif c == "}":
                depth -= 1
                if depth == 0:
                    end = i + 1
                    break
    raw = html[start:end]
    try:
        data = json.loads(raw)
        sd = data.get("streamingData", {})
        formats = sd.get("formats", [])
        adaptive = sd.get("adaptiveFormats", [])
        print("formats:", len(formats), "adaptive:", len(adaptive))
